#!/usr/bin/env python3
# PT_FREEORG_V1 — free-form org chart: pure reports-to tree (drag anyone onto anyone), teams kept as
# colour tags (functionId untouched). Replaces the department-based tree render and applyDrop. Idempotent.
import sys, base64
SENT="function freeParent("
PAIRS=[('', 'ICB2YXIgY2VvPWNvbXBhbnkuY2VvTWVtYmVySWQ7CiAgdmFyIHRyZWU9ZnJlZVRyZWVIVE1MKGNlbyk7'), ('', '')]
def d64(s): return base64.b64decode(s).decode("utf-8")
def main():
    if len(sys.argv)<2: sys.exit("usage: python3 build_freeorg_patch.py index.html")
    p=sys.argv[1]; d=open(p,encoding="utf-8").read()
    if SENT in d: print("PT_FREEORG_V1 already present — no-op."); return
    for i,(eo,en) in enumerate(PAIRS):
        o=d64(eo); n=d64(en); c=d.count(o)
        if c!=1: sys.exit("ABORT: hunk %d anchor count %d (expected 1)"%(i,c))
        d=d.replace(o,n,1)
    open(p,"w",encoding="utf-8").write(d); print("PT_FREEORG_V1 applied OK (2 hunks).")
main()
